package com.daniil.wristlens.wear;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;
import com.daniil.wristlens.shared.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;
import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import org.robolectric.util.ReflectionHelpers;
import java.time.Duration;import java.util.*;import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(sdk=34,qualifiers="en-rUS-w240dp-h240dp-round-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE) @LooperMode(LooperMode.Mode.PAUSED)
public class MenuUpgradeTest {
 Activity a;
 @Before public void before(){a=Robolectric.buildActivity(Activity.class).setup().get();Strings.init(a);ActionFeedback.enabled(a,true);}
 @After public void after(){for(Dialog d:new ArrayList<>(ShadowDialog.getShownDialogs()))d.dismiss();a.finish();}
 @Test public void menuButtonsHapticEvenWhenClickListenerIsReplacedAndRespectMute(){Button b=Controls.button(a,"First",()->{});b.setOnClickListener(v->{});b.performClick();assertEquals(HapticFeedbackConstants.VIRTUAL_KEY,Shadows.shadowOf(b).lastHapticFeedbackPerformed());ActionFeedback.enabled(a,false);Button muted=Controls.button(a,"Muted",()->{});muted.performClick();assertEquals(-1,Shadows.shadowOf(muted).lastHapticFeedbackPerformed());ActionFeedback.enabled(a,true);Button disabled=Controls.button(a,"Disabled",()->fail("Disabled button invoked"));disabled.setEnabled(false);disabled.performClick();assertEquals(-1,Shadows.shadowOf(disabled).lastHapticFeedbackPerformed());}
 private RoundMenuFrame menu(int height){ScrollView scroll=new ScrollView(a);LinearLayout col=new LinearLayout(a);col.addView(new View(a),new LinearLayout.LayoutParams(100,height));scroll.addView(col);RoundMenuFrame root=new RoundMenuFrame(a,scroll);a.setContentView(root);RoundMenuTest.layout(root,480);return root;}
 @Test public void bezelTicksOnlyWhenContentMovesAndHonoursMute(){RoundMenuFrame root=menu(1600);root.rotate(-2);assertEquals(-1,Shadows.shadowOf(root).lastHapticFeedbackPerformed());root.rotate(2);assertEquals(HapticFeedbackConstants.SEGMENT_TICK,Shadows.shadowOf(root).lastHapticFeedbackPerformed());RoundMenuFrame shortMenu=menu(20);shortMenu.rotate(2);assertEquals(-1,Shadows.shadowOf(shortMenu).lastHapticFeedbackPerformed());ActionFeedback.enabled(a,false);RoundMenuFrame muted=menu(1600);muted.rotate(2);assertTrue(((ScrollView)muted.getChildAt(0)).getScrollY()>0);assertEquals(-1,Shadows.shadowOf(muted).lastHapticFeedbackPerformed());}
 @Test public void fineSliderStepsGiveATickOnlyOnValueChange(){Controls.settings(a,MenuInputTest.state(),true,c->{});GallerySettingsTest.text(ShadowDialog.getLatestDialog(),"Zoom · 1.0×").performClick();RoundMenuFrame root=RoundMenuTest.frame(ShadowDialog.getLatestDialog());RoundMenuTest.layout(root,480);root.rotate(-1);assertEquals(-1,Shadows.shadowOf(root).lastHapticFeedbackPerformed());root.rotate(.4f);assertEquals(-1,Shadows.shadowOf(root).lastHapticFeedbackPerformed());root.rotate(.6f);assertEquals(HapticFeedbackConstants.SEGMENT_TICK,Shadows.shadowOf(root).lastHapticFeedbackPerformed());}
 @Test public void cameraAndCaptureAreOnePageAndLongHelpIsOnlyInInstructions(){Controls.settings(a,()->Wire.object("capture",Wire.object("background",true)),true,c->{});Dialog d=ShadowDialog.getLatestDialog();assertTrue(GallerySettingsTest.has(d,"Background capture"));assertTrue(GallerySettingsTest.has(d,Strings.tr(com.daniil.wristlens.shared.R.string.wl_225)));assertFalse(GallerySettingsTest.has(d,Strings.tr(com.daniil.wristlens.shared.R.string.wl_224)));assertFalse(GallerySettingsTest.has(d,Strings.tr(com.daniil.wristlens.shared.R.string.wl_300)));CaptureSettingsUi.help(a,true);assertTrue(GallerySettingsTest.has(ShadowDialog.getLatestDialog(),Strings.tr(com.daniil.wristlens.shared.R.string.wl_224)));assertTrue(GallerySettingsTest.has(ShadowDialog.getLatestDialog(),Strings.tr(com.daniil.wristlens.shared.R.string.help_idle)));}
 @Test public void rejectedLiveSettingRollsBackOnTheSamePage(){Controls.settings(a,()->Wire.object("capture",Wire.object("background",true)),true,c->{});Dialog d=ShadowDialog.getLatestDialog();GallerySettingsTest.text(d,"Background capture").performClick();Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(450));assertTrue(d.isShowing());assertTrue(((CheckBox)GallerySettingsTest.text(d,"Background capture")).isChecked());}
 @Test public void savingCombinesPhoneAndWatchAndKeepsParentAfterPickingQuality()throws Exception{GallerySettingsTest.FakeMedia media=new GallerySettingsTest.FakeMedia(a);try{SavingSettings.show(a,media,"node",Wire.object("folder","DCIM/Camera"));Dialog d=ShadowDialog.getLatestDialog();assertTrue(GallerySettingsTest.has(d,"On the phone"));assertTrue(GallerySettingsTest.has(d,"On the watch"));assertTrue(GallerySettingsTest.has(d,Strings.tr(com.daniil.wristlens.shared.R.string.wl_extra_01)));assertFalse(GallerySettingsTest.has(d,Strings.tr(com.daniil.wristlens.shared.R.string.copy_settings_help)));GallerySettingsTest.views(d).stream().filter(v->v instanceof Button b&&b.getText().toString().startsWith("Photo compression")).findFirst().orElseThrow().performClick();GallerySettingsTest.text(ShadowDialog.getLatestDialog(),"JPEG · 85% · up to 1920 px").performClick();Shadows.shadowOf(Looper.getMainLooper()).idle();assertTrue(d.isShowing());assertEquals("balanced",CopySettings.read(a).photo());assertEquals("Saved",ShadowToast.getTextOfLatestToast());RoundMenuFrame root=RoundMenuTest.frame(d);RoundMenuTest.layout(root,480);RoundMenuTest.save(root,"saving-unified");}finally{media.close();}}
 @Test public void russianMenuAndVersionWrapOnSmallAndLargeRoundScreens()throws Exception{RuntimeEnvironment.setQualifiers("ru-rRU-w240dp-h240dp-round-xhdpi");Strings.init(a);for(int size:new int[]{384,480})for(float scale:new float[]{1f,1.3f}){RuntimeEnvironment.setFontScale(scale);try(var ctl=Robolectric.buildActivity(WatchActivity.class).create()){WatchActivity watch=ctl.get();((View)ReflectionHelpers.getField(watch,"more")).performClick();Dialog menu=ShadowDialog.getLatestDialog();RoundMenuFrame root=RoundMenuTest.frame(menu);RoundMenuTest.layout(root,size);for(View v:GallerySettingsTest.views(menu))if(v instanceof TextView text&&text.getLayout()!=null)for(int line=0;line<text.getLineCount();line++)assertTrue(text.getText().toString(),text.getLayout().getLineMax(line)<=text.getWidth()-text.getTotalPaddingLeft()-text.getTotalPaddingRight()+2);RoundMenuTest.save(root,"menu-ru-"+size+"-"+scale);((ScrollView)root.getChildAt(0)).scrollTo(0,10000);RoundMenuTest.save(root,"version-ru-"+size+"-"+scale);menu.dismiss();}}RuntimeEnvironment.setFontScale(1f);}
 @Test public void menuHasInlineFeedbackVersionAndNoSinglePurposeSection()throws Exception{try(var ctl=Robolectric.buildActivity(WatchActivity.class).create()){WatchActivity watch=ctl.get();((View)ReflectionHelpers.getField(watch,"more")).performClick();Dialog menu=ShadowDialog.getLatestDialog();assertFalse(GallerySettingsTest.has(menu,"Watch settings"));assertFalse(GallerySettingsTest.has(menu,"Capture settings"));assertTrue(GallerySettingsTest.has(menu,"Files and saving"));assertTrue(GallerySettingsTest.has(menu,"Vibration for actions"));assertTrue(GallerySettingsTest.has(menu,"WristLens · 1.8.0"));assertTrue(GallerySettingsTest.has(menu,"Capture sounds"));assertFalse(GallerySettingsTest.views(menu).stream().anyMatch(v->v instanceof TextView t&&t.getText().toString().contains("ChatGPT")));RoundMenuFrame root=RoundMenuTest.frame(menu);RoundMenuTest.layout(root,480);RoundMenuTest.save(root,"menu-unified");((ScrollView)root.getChildAt(0)).fullScroll(View.FOCUS_DOWN);RoundMenuTest.save(root,"menu-version");}}
}
